SELECT
FROM quote q LEFT JOIN content_feature_snapshot fs ON fs.content_id = q.id LEFT JOIN quote_tag qt ON qt.quote_id = q.id LEFT JOIN tag t ON t.id = qt.tag_id LEFT JOIN quote_topic qt2 ON qt2.quote_id = q.id AND qt2.deleted = 0 AND qt2.status = 1 WHERE q.deleted = 0 AND q.status = 1 AND t.name IN
#{tag}
